#include <iostream>
#include <algorithm>
using namespace std;

int n;
int a[100010], b[100010], cnt[100010];

void solve() {
    cin >> n;
    for (int i = 1; i <= n; i++)
        a[i] = b[i] = cnt[i] = 0;
    for (int i = 1; i <= n; i++) {
        int u, v;
        cin >> u >> v;
        b[u] = a[u];
        a[u] = v;
        b[v] = a[v];
        a[v] = u;
    }
    bool flag = false;
    for (int i = 1; i <= n; i++) {
        if (cnt[i])
            continue;
        int u = i, last = a[u];
        int v = a[u] + b[u] - last;
        while (!cnt[v]) {
            cnt[v] = cnt[u] + 1;
            last = u;
            u = v;
            v = a[u] + b[u] - last;
        }
        if (cnt[i] % 2 != 0)
            flag = true;
    }
    if (flag)
        cout << 3 << endl;
    else
        cout << 2 << endl;
}

int main() {
    int t;
    cin >> t;
    while (t--)
        solve();
    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

int n;
int a[110];
long long f[110][110];

int main() {
    cin >> n;
    for (int i = 1; i <= n; i++)
        cin >> a[i];
    for (int i = 1; i <= n; i++)
        for (int l = 1, r = i; r <= n; l++, r++)
            for (int k = l; k <= r; k++)
                f[l][r] = max(f[l][r], f[l][k - 1] + f[k + 1][r] + a[l - 1] + a[r + 1]);
    cout << f[1][n] << endl;
    return 0;
}
